INSERT INTO public.cabin_ships (slug,ship,line,class,source,source_detail,svg_version,extracted_on,deck_count,total_cabins,decks,category_counts,color_legend,notes) VALUES ('wonder-of-the-seas','Wonder of the Seas','Royal Caribbean','Oasis','deckmaps.com','Cabin geometry (number, deck, raw x/y, fill colour) parsed from deckmaps.com versioned deck SVGs (/data/out/royal-caribbean/wonder-of-the-seas/v2491/deck-<N>.<hash>.svg), one .cabinShape[data-cabin] element per stateroom. Category legend built by matching each fill colour to Royal Caribbean stateroom categories, verified per-colour against cruisedeckplans.com stateroom-details pages and exact category counts.','v2491','2026-07-26',11,2886,'{3,6,7,8,9,10,11,12,14,17,18}','{"Ocean View": 147, "Interior": 545, "Ocean View Balcony": 1430, "Junior Suite": 114, "Promenade View Interior": 26, "Boardwalk Balcony": 221, "AquaTheater Suite - 2 Bedroom": 6, "Boardwalk and Park View": 70, "Central Park Balcony": 256, "Ultra Spacious Ocean View": 8, "Family Interior": 4, "Family Balcony": 5, "AquaTheater Suite - 1 Bedroom": 6, "Grand Suite": 28, "Royal Loft Suite": 1, "Crown Loft Suite": 8, "Owners Suite": 10, "Ultimate Family Suite": 1}'::jsonb,'{"#6e62ab": "Ocean View Balcony", "#39b4cd": "Ocean View Balcony", "#e5687f": "Ocean View Balcony", "#efbf65": "Ocean View Balcony", "#d7b29d": "Interior", "#638595": "Interior", "#1b934d": "Interior", "#d0ab97": "Interior", "#c8e8ea": "Interior", "#b76118": "Central Park Balcony", "#d18c0f": "Boardwalk Balcony", "#ee91a7": "Boardwalk and Park View", "#fdeb38": "Ocean View", "#7fc9c6": "Ocean View", "#c1bcd5": "Promenade View Interior", "#b5b3cd": "Promenade View Interior", "#50316e": "Junior Suite", "#07c0ff": "Junior Suite", "#503776": "Junior Suite", "#d71d4c": "Grand Suite", "#a9a735": "Owners Suite", "#b290a5": "Crown Loft Suite", "#c9e2b0": "Ultra Spacious Ocean View", "#a2c76a": "Family Balcony", "#8ac9ae": "Family Interior", "#df76a3": "AquaTheater Suite - 1 Bedroom", "#846a7c": "AquaTheater Suite - 2 Bedroom", "#da0781": "AquaTheater Suite - 2 Bedroom", "#d80e80": "AquaTheater Suite - 2 Bedroom", "#836b7d": "AquaTheater Suite - 2 Bedroom", "#505aa7": "Royal Loft Suite", "#007d80": "Ultimate Family Suite"}'::jsonb,'{"completeness": "FULL grid: every stateroom on every guest deck (decks 3,6,7,8,9,10,11,12,14,17,18). Decks 4,5,15,16 and public areas carry no staterooms in the source. Total 2886 matches deckmaps advertised count; cruisedeckplans category total is ~2892 (a few accessible/duplicate rows counted differently).", "category": "deckmaps encodes category only via cabin fill colour. 32 distinct fills map to 18 Royal Caribbean categories (several categories use more than one colour shade). See colorLegend.", "section": "DERIVED heuristic. Length axis and bow direction detected per deck from cabin numbering, confirmed by the aft AquaTheater suites; section = forward/mid/aft thirds of the hull length. Approximate.", "side": "DERIVED heuristic. Geometric split of the beam into two rows, labelled port/starboard assuming a standard viewed-from-above deck plan with the verified bow direction. Could be uniformly mirrored; validate against a known cabin before relying on it.", "obstructed": "deckmaps SVGs carry no obstructed-view flag; obstructed=false for all (source does not encode obstruction, not asserted as clear-view)."}'::jsonb);
